    "arid": {"pos":"adjective","definition":"very dry with little rainfall","example":"Cacti are well adapted to survive in arid desert environments.","antonyms":["humid","wet","moist"]},
    "adverse": {"pos":"adjective","definition":"harmful or unfavorable","example":"Pesticides can have adverse effects on bee populations.","antonyms":["favorable","beneficial","positive"]},
    "entice": {"pos":"verb","definition":"to attract by offering something pleasant","example":"Flowers use bright colors and sweet nectar to entice pollinating insects.","antonyms":["repel","deter"]},
    "encroachment": {"pos":"noun","definition":"gradual intrusion into another's area or rights","example":"The encroachment of farms into forests has reduced the habitat of orangutans.","antonyms":["withdrawal","retreat"]},
    "avert": {"pos":"verb","definition":"to prevent something bad from happening","example":"Quick action by officials helped avert a famine after the drought.","antonyms":["cause","provoke"]},
    "exceedingly": {"pos":"adverb","definition":"extremely; to a very great degree","example":"Fossils of soft-bodied organisms are exceedingly rare.","antonyms":["slightly","barely"],"arabic":"للغاية"},
    "majestic": {"pos":"adjective","definition":"impressive, grand, and beautiful","example":"The majestic peaks of the Himalayas were formed by colliding tectonic plates.","antonyms":["humble","modest","unimpressive"]},
    "meticulously": {"pos":"adverb","definition":"with great care and attention to detail","example":"The museum staff meticulously restored the damaged Renaissance painting.","antonyms":["carelessly","sloppily"]},
    "perilous": {"pos":"adjective","definition":"full of danger or risk","example":"The journey across the Atlantic was perilous for early European sailors.","antonyms":["safe","secure"]},
    "of the essence": {"pos":"phrase","definition":"extremely important; essential","example":"In emergency medicine, time is of the essence when treating heart attacks.","antonyms":["unimportant","inessential"]},
    "insights into": {"pos":"phrase","definition":"a clear understanding of something","example":"The diaries provide valuable insights into daily life during the Civil War."},
    "intrepid": {"pos":"adjective","definition":"fearless and adventurous","example":"Intrepid explorers mapped the sources of the Nile in the nineteenth century.","antonyms":["timid","cowardly","fearful"]},
    "overwhelming strategy": {"pos":"phrase","definition":"a plan relying on very powerful, superior force","example":"The army relied on an overwhelming strategy, attacking with far greater numbers.","arabic":"استراتيجية ساحقة"},
    "fly in the face of": {"pos":"phrase","definition":"to directly contradict or oppose","example":"The new findings fly in the face of long-held beliefs about dinosaur behavior.","antonyms":["agree with","conform to"]},
    "hit the ground running": {"pos":"phrase","definition":"to start an activity quickly and successfully","example":"The research team hit the ground running, collecting samples on their first day.","antonyms":["get off to a slow start"]},
    "colloquially": {"pos":"adverb","definition":"in informal, everyday language","example":"The killer whale is colloquially known as the orca.","antonyms":["formally"]},
    "illicit": {"pos":"adjective","definition":"illegal or forbidden by law or custom","example":"The illicit trade in ivory has endangered elephant populations across Africa.","antonyms":["legal","lawful","licit"]},
    "breadth of duties": {"pos":"phrase","definition":"a wide variety of responsibilities","example":"The breadth of duties of a colonial governor included taxation, defense, and justice."},
    "prolific": {"pos":"adjective","definition":"producing a great amount of work or offspring","example":"Picasso was a prolific artist who created thousands of works.","antonyms":["unproductive","barren"]},
    "dense": {"pos":"adjective","definition":"thick, heavy, or closely packed together","example":"Dense forests once covered most of central Europe.","antonyms":["sparse","thin","light"]},
    "engrossing": {"pos":"adjective","definition":"so interesting that it holds all your attention","example":"Students found the documentary on ancient Egypt truly engrossing.","antonyms":["boring","dull","tedious"],"arabic":"آسر / ممتع"},
    "facilitate": {"pos":"verb","definition":"to make an action or process easier or faster","example":"Enzymes facilitate chemical reactions in living cells.","antonyms":["hinder","impede","obstruct"]},
    "anticipated": {"pos":"verb","definition":"expected or predicted","example":"The harvest was smaller than farmers had anticipated because of the late frost.","antonyms":["unexpected"]},
    "sow the seeds": {"pos":"phrase","definition":"to start a process that develops later","example":"Economic hardship helped sow the seeds of revolution in eighteenth-century France.","antonyms":["stifle","nip in the bud"],"arabic":"يمهد لـ / يزرع بذور"},
    "advocate": {"pos":"noun","definition":"a person who publicly supports a cause","example":"John Muir was a passionate advocate for the protection of wilderness areas.","antonyms":["opponent","critic"]},
    "bleak": {"pos":"adjective","definition":"cold, gloomy, and without hope","example":"Early explorers described the Arctic tundra as a bleak and empty landscape.","antonyms":["cheerful","bright","promising"]},
    "ultimately": {"pos":"adverb","definition":"in the end; finally","example":"The empire ultimately collapsed under the weight of invasions and economic decline.","antonyms":["initially","firstly"]},
    "scathing": {"pos":"adjective","definition":"severely critical and harsh","example":"Critics published scathing reviews of the first Impressionist exhibition.","antonyms":["complimentary","flattering","mild"]},
    "took the reins": {"pos":"phrase","definition":"took control or leadership","example":"After her father's death, Elizabeth I took the reins of a divided kingdom.","antonyms":["stepped down","handed over"]},
    "vigor": {"pos":"noun","definition":"physical or mental strength and energy","example":"Young trees grow with great vigor after a forest fire clears the canopy.","antonyms":["weakness","lethargy","feebleness"],"arabic":"حيوية / نشاط"},
