    "disheveled": {"pos":"adjective","definition":"untidy in appearance; messy","example":"Witnesses described the shipwreck survivors as exhausted and disheveled.","antonyms":["neat","tidy","well-groomed"]},
    "dire": {"pos":"adjective","definition":"extremely serious or terrible; urgent","example":"The drought had dire consequences for the farming communities of the ancient Near East.","antonyms":["mild","minor"]},
    "detectable": {"pos":"adjective","definition":"able to be noticed or discovered","example":"The tremors were barely detectable without sensitive seismic instruments.","antonyms":["undetectable","imperceptible"],"arabic":"قابل للاكتشاف"},
    "justified": {"pos":"adjective","definition":"supported by good reasons or evidence","example":"The scientist's conclusion was justified by years of careful field observations.","antonyms":["unjustified","groundless"],"arabic":"مُبرَّر"},
    "flourish": {"pos":"verb","definition":"to grow well and be successful","example":"Coral reefs flourish in warm, shallow waters with plenty of sunlight.","antonyms":["decline","wither","fail"]},
    "propagate": {"pos":"verb","definition":"to breed or reproduce; to increase in number","example":"Many plants propagate by sending out underground runners rather than seeds.","antonyms":["die out"]},
    "dormant": {"pos":"adjective","definition":"temporarily inactive, as if asleep","example":"Some seeds remain dormant in the desert soil for years until rain arrives.","antonyms":["active","awake"]},
    "at random": {"pos":"phrase","definition":"without any plan, order, or pattern","example":"Participants in the study were chosen at random from the city population.","antonyms":["systematically","deliberately"],"arabic":"عشوائياً"},
    "abundantly": {"pos":"adverb","definition":"in large amounts; plentifully","example":"Wild berries grew abundantly along the riverbanks during the summer months.","antonyms":["scarcely","sparsely"]},
    "status": {"pos":"noun","definition":"social or professional position and importance","example":"In many ancient societies, owning cattle was a sign of high social status.","antonyms":["obscurity"]},
    "embraces": {"pos":"verb","definition":"accepts or adopts something willingly; hugs","example":"The modern art movement embraces bold colors and unconventional materials.","antonyms":["rejects","refuses"]},
    "instigated": {"pos":"verb","definition":"caused or started something, often by encouraging others","example":"Rising taxes instigated a series of protests among colonial merchants.","antonyms":["prevented","halted"]},
    "imitation": {"pos":"noun","definition":"the act of copying someone or something","example":"Young birds learn their songs through imitation of adult males.","antonyms":["originality","invention"],"arabic":"تقليد / محاكاة"},
    "dietetics": {"pos":"noun","definition":"the scientific study of diet and nutrition","example":"Advances in dietetics have improved treatment for patients with diabetes."},
    "didactic": {"pos":"adjective","definition":"intended to teach, especially a moral lesson","example":"Medieval paintings were often didactic, teaching religious stories to people who could not read.","antonyms":["entertaining"]},
    "context": {"pos":"noun","definition":"the conditions or setting in which something happens","example":"Historians must study each document in the context of its time.","arabic":"سياق"},
    "depicts": {"pos":"verb","definition":"shows or represents in a picture or words","example":"The cave painting depicts a group of hunters chasing wild bison.","antonyms":["conceals"]},
    "impose on": {"pos":"phrase","definition":"to force a rule, tax, or burden on someone","example":"The empire chose to impose on its provinces a heavy tax on grain.","antonyms":["lift from","exempt"]},
    "loathe": {"pos":"verb","definition":"to hate very strongly","example":"Many early farmers came to loathe the locusts that destroyed their crops.","antonyms":["love","adore"]},
    "catastrophes": {"pos":"noun","definition":"sudden events causing great damage or suffering","example":"Natural catastrophes such as volcanic eruptions have shaped human history.","antonyms":["blessings"]},
    "assisted in": {"pos":"phrase","definition":"helped with doing something","example":"Local guides assisted in mapping the uncharted river valleys.","antonyms":["hindered","obstructed"]},
    "criteria": {"pos":"noun","definition":"standards used for judging or deciding something","example":"Scientists use strict criteria to classify a new species."},
    "regarded": {"pos":"verb","definition":"considered or thought of in a particular way","example":"Darwin's theory was regarded as revolutionary by many scientists of his era.","antonyms":["disregarded","ignored"]},
    "conceal": {"pos":"verb","definition":"to hide something or keep it secret","example":"Many insects use camouflage to conceal themselves from predators.","antonyms":["reveal","expose","disclose"]},
    "paradoxes": {"pos":"noun","definition":"statements or situations that seem contradictory but may be true","example":"Philosophers have debated the paradoxes of motion since ancient Greece."},
    "overshadowed": {"pos":"verb","definition":"made something seem less important by comparison","example":"Her early scientific work was overshadowed by her husband's fame.","antonyms":["highlighted","emphasized"]},
    "dwellers": {"pos":"noun","definition":"people or animals that live in a particular place","example":"Cliff dwellers in the American Southwest built homes into canyon walls."},
    "fractures": {"pos":"noun","definition":"cracks or breaks, especially in rock or bone","example":"Water seeps into fractures in the rock and widens them when it freezes.","arabic":"كسور / شقوق"},
    "immobile": {"pos":"adjective","definition":"not moving or unable to move","example":"Barnacles are immobile as adults, attaching themselves permanently to rocks.","antonyms":["mobile","moving"]},
    "intimidating": {"pos":"adjective","definition":"frightening or making someone feel less confident","example":"The sheer size of the dinosaur skeleton is intimidating to young museum visitors.","antonyms":["reassuring","comforting"]},
    "endowing": {"pos":"verb","definition":"providing someone or something with a quality or resource","example":"Wealthy patrons were endowing universities with funds for new libraries.","antonyms":["depriving"]},
    "deviate": {"pos":"verb","definition":"to move away from a usual path or standard","example":"Migrating birds rarely deviate from their traditional flight routes.","antonyms":["conform","follow"]},
    "neglected": {"pos":"verb","definition":"failed to give proper care or attention to","example":"The ancient canals were neglected and eventually filled with silt.","antonyms":["attended to","maintained"],"arabic":"أهمل"},
    "uniformly": {"pos":"adverb","definition":"in the same way throughout; consistently","example":"The sediment layers were uniformly thick across the entire basin.","antonyms":["unevenly","irregularly"],"arabic":"بشكل موحّد"},
    "potent": {"pos":"adjective","definition":"very powerful or strong in effect","example":"Some frogs produce a potent toxin that protects them from predators.","antonyms":["weak","ineffective"],"arabic":"قوي / فعّال"},
