    "verify": {"pos":"verb","definition":"to prove or check that something is true","example":"Scientists repeated the experiment to verify the original results.","antonyms":["disprove","refute"],"arabic":"يتحقق من"},
    "adept": {"pos":"adjective","definition":"very skilled at something","example":"Early Polynesian sailors were adept at navigating by the stars.","antonyms":["inept","clumsy"]},
    "attributes": {"pos":"noun","definition":"qualities or features belonging to someone or something","example":"Speed and endurance are key attributes of migratory birds."},
    "credible": {"pos":"adjective","definition":"able to be believed; trustworthy","example":"The historian found the eyewitness account credible and well documented.","antonyms":["unbelievable","implausible"]},
    "deceived": {"pos":"verb","definition":"tricked someone into believing something false","example":"Predators are often deceived by the eye-like spots on butterfly wings.","antonyms":["enlightened"]},
    "incredible": {"pos":"adjective","definition":"impossible or very hard to believe","example":"Arctic terns make an incredible annual journey between the poles.","antonyms":["believable","credible"]},
