    "match": {"pos":"verb","definition":"to be equal to something","example":"Few modern bridges can match the durability of Roman stone arches.","antonyms":["differ"],"arabic":"يضاهي / يساوي"},
    "deceiving": {"pos":"adjective","definition":"giving a false impression; misleading","example":"The calm surface of the lake can be deceiving because strong currents flow below.","antonyms":["honest","accurate"]},
    "static": {"pos":"adjective","definition":"not moving or changing","example":"Early scientists believed that the continents were static and never moved.","antonyms":["dynamic","changing"],"arabic":"ثابت / ساكن"},
