    "dramatically": {"pos":"adverb","definition":"suddenly and to a very large degree","example":"Global temperatures rose dramatically at the end of the last ice age.","antonyms":["slightly","marginally"]},
    "refined": {"pos":"verb","definition":"made purer or improved by small changes","example":"Over centuries, potters refined their techniques for glazing ceramics.","antonyms":["unrefined","worsened"]},
    "norms": {"pos":"noun","definition":"accepted standards of behavior in a group","example":"Social norms often determine how children are raised in a culture.","antonyms":["exceptions"]},
    "signal": {"pos":"verb","definition":"to communicate information by a sign or action","example":"Honeybees signal the location of food through a special dance.","antonyms":["conceal"],"arabic":"يُشير / يُرسل إشارة"},
