    "devastated": {"pos":"verb","definition":"destroyed or severely damaged","example":"The volcanic eruption devastated the Roman town of Pompeii.","antonyms":["restored","rebuilt"]},
    "inadvertently": {"pos":"adverb","definition":"without intending to; by accident","example":"European settlers inadvertently introduced rats to many Pacific islands.","antonyms":["deliberately","intentionally"]},
    "highlights": {"pos":"verb","definition":"draws special attention to; emphasizes","example":"The study highlights the importance of wetlands for migrating birds.","antonyms":["downplays","obscures"]},
    "relict": {"pos":"adjective","definition":"surviving from an earlier period; remaining","example":"Relict forests in the mountains preserve plants from the last ice age."},
    "empirical evidence": {"pos":"phrase","definition":"information gained through observation or experiment","example":"The hypothesis was rejected because there was no empirical evidence to support it.","antonyms":["speculation","theory"]},
    "rebellion": {"pos":"noun","definition":"an armed or organized resistance against authority","example":"The peasant rebellion spread quickly across the southern provinces.","antonyms":["obedience","submission"]},
    "discontent": {"pos":"noun","definition":"dissatisfaction with one's situation","example":"Growing discontent among workers led to the first labor unions.","antonyms":["contentment","satisfaction"]},
    "friction": {"pos":"noun","definition":"disagreement or conflict between people or groups","example":"Trade disputes caused friction between the colonies and Britain.","antonyms":["harmony","agreement"]},
    "trend": {"pos":"noun","definition":"a general direction of change or development","example":"Researchers observed a trend toward smaller family sizes in urban areas."},
