    "substantiated": {"pos":"verb","definition":"supported or confirmed with evidence","example":"The theory was substantiated by fossils found on several continents.","antonyms":["disproved","refuted"],"arabic":"أُثبت / دُعِم بالأدلة"},
    "heterogeneous": {"pos":"adjective","definition":"made up of different or varied parts","example":"The city had a heterogeneous population of merchants, sailors, and artisans.","antonyms":["homogeneous","uniform"]},
    "enjoy": {"pos":"verb","definition":"to have or experience something good","example":"Coastal regions enjoy a milder climate than inland areas.","antonyms":["lack","suffer"],"arabic":"يتمتع بـ"},
    "reveal": {"pos":"verb","definition":"to show or make known something hidden","example":"Ice cores reveal how the Earth's climate changed over thousands of years.","antonyms":["conceal","hide"],"arabic":"يكشف"},
    "cramped": {"pos":"adjective","definition":"uncomfortably small or crowded","example":"Factory workers in the nineteenth century often lived in cramped apartments.","antonyms":["spacious","roomy"]},
